-- 54. Seed de las 9 Instituciones Educativas Activas y Contexto Inicial
ON CONFLICT (legacy_db_name) DO NOTHING;
SELECT s.id, 2026, '2026-01-19'::DATE, '2026-11-30'::DATE, FALSE
FROM schools s
ON CONFLICT (school_id, year) DO NOTHING;
SELECT
  s.id,
  2026,
  p.period_number,
  p.period_name,
  25.00,
  p.start_date::DATE,
  p.end_date::DATE,
  (p.period_number = 1)
FROM schools s
CROSS JOIN (
  VALUES
    (1, 'PRIMER PERIODO', '2026-01-19', '2026-03-27'),
    (2, 'SEGUNDO PERIODO', '2026-03-30', '2026-06-12'),
    (3, 'TERCER PERIODO', '2026-07-06', '2026-09-11'),
    (4, 'CUARTO PERIODO', '2026-09-14', '2026-11-27')
) AS p(period_number, period_name, start_date, end_date)
WHERE NOT EXISTS (
  SELECT 1 FROM academic_periods ap WHERE ap.school_id = s.id AND ap.academic_year = 2026 AND ap.period_number = p.period_number
);
VALUES (
